1	/** Flat fee added to every premium, regardless of the items insured. */
2	const PROCESSING_FEE = 5;
3	
4	/** Base premium of each insurable item type. */
5	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
6	  sword: 100,
7	  amulet: 60,
8	  staff: 80,
9	  potion: 40,
10	  rune: 25,
11	  moonstone: 25,
12	};
13	
14	/** Initial assessment surcharge on a customer's first insurance. */
15	const FIRST_INSURANCE_RATE = 0.1;
16	
17	export type Customer = { yearsWithMHPCO: number };
18	
19	export type Scenario = {
20	  customer: Customer;
21	  steps: Step[];
22	};
23	
24	export type Step = {
25	  op: string;
26	  items: Item[];
27	};
28	
29	export type Item = { type: string } & Record<string, unknown>;
30	
31	export type Result = { premium: number };
32	
33	export type ScenarioOutcome = { results: Result[] };
34	
35	/** A block is exactly this many items of one and the same type. */
36	const BLOCK_SIZE = 3;
37	
38	/** Special base premium charged for a complete block, instead of the per-item sum. */
39	const BLOCK_BASE_PREMIUM = 60;
40	
41	/** Number of items of each type on a policy. */
42	const countByType = (items: Item[]): Map<string, number> => {
43	  const counts = new Map<string, number>();
44	  for (const item of items) {
45	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
46	  }
47	  return counts;
48	};
49	
50	/** Base premium of a single item of the given type, before block pricing or surcharge. */
51	const basePremiumOfType = (type: string): number => BASE_PREMIUM_BY_TYPE[type];
52	
53	/** Base premium of a single item, before any block pricing or surcharge. */
54	const itemBasePremium = (item: Item): number => basePremiumOfType(item.type);
55	
56	/** Base premium for all items of one and the same type. */
57	const groupBasePremium = (type: string, count: number): number =>
58	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * basePremiumOfType(type);
59	
60	/** Base premium of a policy covering the given items. */
61	const calculateBasePremium = (items: Item[]): number =>
62	  [...countByType(items)].reduce(
63	    (total, [type, count]) => total + groupBasePremium(type, count),
64	    0,
65	  );
66	
67	/** Risk surcharge charged on the base premium of a cursed item. */
68	const CURSE_RATE = 0.5;
69	
70	/** Enchantment level from which an item counts as highly enchanted. */
71	const HIGH_ENCHANTMENT_LEVEL = 5;
72	
73	/** Risk surcharge charged on the base premium of a highly enchanted item. */
74	const HIGH_ENCHANTMENT_RATE = 0.3;
75	
76	/** True when the item is enchanted strongly enough to attract the surcharge. */
77	const isHighlyEnchanted = (item: Item): boolean =>
78	  typeof item.enchantment === "number" &&
79	  item.enchantment >= HIGH_ENCHANTMENT_LEVEL;
80	
81	/** Combined rate of the surcharges an item attracts. */
82	const itemSurchargeRate = (item: Item): number => {
83	  const curseRate = item.cursed ? CURSE_RATE : 0;
84	  const enchantmentRate = isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_RATE : 0;
85	  return curseRate + enchantmentRate;
86	};
87	
88	/** Surcharges an individual item attracts, charged on its own base premium. */
89	const itemSurcharges = (item: Item): number =>
90	  itemBasePremium(item) * itemSurchargeRate(item);
91	
92	/** Surcharges that attach to individual items rather than to the whole policy. */
93	const calculateItemSurcharges = (items: Item[]): number =>
94	  items.reduce((sum, item) => sum + itemSurcharges(item), 0);
95	
96	/** Years of business from which a customer counts as long-standing. */
97	const LOYALTY_YEARS = 2;
98	
99	/** Discount a long-standing customer receives on the policy base premium. */
100	const LOYALTY_RATE = 0.2;
101	
102	/** Surcharges that attach to the policy as a whole, charged on its base premium. */
103	const calculatePolicySurcharges = (
104	  policyBasePremium: number,
105	  customer: Customer,
106	): number => {
107	  const loyaltyRate =
108	    customer.yearsWithMHPCO >= LOYALTY_YEARS ? -LOYALTY_RATE : 0;
109	  return policyBasePremium * (FIRST_INSURANCE_RATE + loyaltyRate);
110	};
111	
112	/** Premiums are rounded up — fractions of a gold piece fall to MHPCO. */
113	const roundPremiumUp = (amount: number): number => Math.ceil(amount);
114	
115	/** Price a policy covering the given items. */
116	const quotePremium = (items: Item[], customer: Customer): number => {
117	  const policyBasePremium = calculateBasePremium(items);
118	  const itemSurcharges = calculateItemSurcharges(items);
119	  const policySurcharges = calculatePolicySurcharges(
120	    policyBasePremium,
121	    customer,
122	  );
123	  return roundPremiumUp(
124	    policyBasePremium + itemSurcharges + policySurcharges + PROCESSING_FEE,
125	  );
126	};
127	
128	export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
129	  results: scenario.steps.map((step) => ({
130	    premium: quotePremium(step.items, scenario.customer),
131	  })),
132	});
